// liveStallFailingSnapshots wraps an in-memory snapshot store and can be told to
// fail every Create call, which the library logs and tolerates while the log
// continues to grow past the node's last snapshot.
type liveStallFailingSnapshots struct {
	inner    *InmemSnapshotStore
	fail     bool
	attempts int
}

func (s *liveStallFailingSnapshots) Create(version SnapshotVersion, index, term uint64,
	configuration Configuration, configurationIndex uint64, trans Transport) (SnapshotSink, error) {
	s.attempts++
	if s.fail {
		return nil, fmt.Errorf("injected snapshot store failure")
	}
	return s.inner.Create(version, index, term, configuration, configurationIndex, trans)
}

func (s *liveStallFailingSnapshots) List() ([]*SnapshotMeta, error) { return s.inner.List() }

func (s *liveStallFailingSnapshots) Open(id string) (*SnapshotMeta, io.ReadCloser, error) {
	return s.inner.Open(id)
