		liveStallEmit(map[string]interface{}{
			"event":                "control_restart_summary",
			"mode":                 mode,
			"local_id":             "A",
			"control_returned":     controlReturned,
			"control_last_applied": controlApplied,
			"snapshot_index":       snapshotIndex,
		})
	}

	for _, id := range ids {
		if r := rafts[id]; r != nil {
			if sf := r.Shutdown(); sf != nil {
				_ = sf.Error()
			}
		}
	}
}

