			liveStallEmit(map[string]interface{}{
				"event":                  name,
				"mode":                   mode,
				"local_id":               "A",
				"newraft_returned":       true,
				"state":                  r.State().String(),
				"last_applied":           r.getLastApplied(),
				"applied_at_snapshot":    r.getLastApplied() == snapshotIndex,
				"fsm_mutate_capacity":    cap(r.fsmMutateCh),
